style.css:
@-moz-document domain("roblox.com") {
/* MAIN PAGE */
  html, body {
    background: #FFF4C7 !important;
    color: #704B2A !important;
  }

  /* TOP NAVBAR */
  .rbx-header {
    background: #FFEFA8 !important;
    border-bottom: 2px solid #E8B85C !important;
    box-shadow: 0 2px 10px rgba(120, 80, 30, 0.12) !important;
  }

  .rbx-header .nav-item,
  .rbx-header a,
  .rbx-header span {
    color: #704B2A !important;
  }

  /* SIDEBAR */
  .rbx-left-col {
    background: #FFF0B8 !important;
    border-right: 2px solid #E8C66A !important;
  }

  .rbx-left-col .font-header-2,
  .rbx-left-col a {
    color: #704B2A !important;
  }

  .rbx-left-col a:hover {
    background: #FFE59A !important;
    border-radius: 12px !important;
  }

  /* MAIN CARDS */
  .card,
  .section,
  .content,
  .catalog-item,
  .game-card,
  .list-item {
    background: #FFF9DF !important;
    border-color: #E8C66A !important;
    border-radius: 16px !important;
  }

  /* BUTTONS */
  button,
  .btn-primary,
  .btn-common,
  .btn-control {
    background: #F6C84C !important;
    color: #5D3D20 !important;
    border: 2px solid #DDA83A !important;
    border-radius: 12px !important;
  }

  button:hover,
  .btn-primary:hover,
  .btn-common:hover {
    background: #FFD968 !important;
    transform: translateY(-1px);
  }

  /* SEARCH BAR */
  input,
  textarea,
  .input-field,
  .search-input {
    background: #FFFBEA !important;
    color: #704B2A !important;
    border: 2px solid #E8C66A !important;
    border-radius: 12px !important;
  }

  input::placeholder {
    color: #B38A55 !important;
  }

  /* LINKS */
  a {
    color: #B87528 !important;
  }

  a:hover {
    color: #E59B32 !important;
  }

  /* DROPDOWNS / POPUPS */
  .dropdown-menu,
  .popover,
  .modal-dialog,
  .modal-content {
    background: #FFF8D9 !important;
    border: 2px solid #E8C66A !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 25px rgba(120,80,30,.15) !important;
  }

  /* AVATARS / THUMBNAILS */
  img {
    border-radius: 12px;
  }

  /* PROFILE HEADER */
  .profile-header,
  .profile-container {
    background: #FFF5C9 !important;
    border-radius: 18px !important;
  }

  /* GAME TILES */
  .game-card-container,
  .game-card {
    border-radius: 18px !important;
    overflow: hidden !important;
  }

  .game-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 7px 18px rgba(190,140,50,.2) !important;
  }

  /* TEXT */
  h1, h2, h3, h4, h5, h6 {
    color: #704B2A !important;
  }

  /* SCROLLBAR ? */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #FFF4C7;
  }

  ::-webkit-scrollbar-thumb {
    background: #E9B94F;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #D99D32;
  }

  /* LITTLE DUCKY FEEL */
  .rbx-header::after {
    content: " ? ";
    color: #D98C28 !important;
    font-size: 18px;
    margin-left: 8px;
  }

  /* SOFT HIGHLIGHT */
  .selected,
  .active,
  .tab-active {
    background: #FFE49A !important;
    border-radius: 12px !important;
  }
}
